use crate::StripAnsiMode;

#[derive(Debug, Clone)]
pub enum VisibleLines {
    /// Show all lines which are included in the line ranges
    Ranges(LineRanges),

    #[cfg(feature = "git")]
    /// Only show lines surrounding added/deleted/modified lines
    DiffContext(usize),
}

impl VisibleLines {
    pub fn diff_mode(&self) -> bool {
        match self {
            Self::Ranges(_) => false,
            #[cfg(feature = "git")]
            Self::DiffContext(_) => true,
        }
    }
}

impl Default for VisibleLines {
    fn default() -> Self {
        VisibleLines::Ranges(LineRanges::default())
    }
}

#[derive(Debug, Clone, Default)]
pub struct Config<'a> {
    /// The explicitly configured language, if any
    pub language: Option<&'a str>,

    /// Whether or not to show/replace non-printable characters like space, tab and newline.
    pub show_nonprintable: bool,

    /// The configured notation for non-printable characters
    pub nonprintable_notation: NonprintableNotation,

    /// How to treat binary content
    pub binary: BinaryBehavior,

    /// The character width of the terminal
    pub term_width: usize,

    /// The width of tab characters.
    /// Currently, a value of 0 will cause tabs to be passed through without expanding them.
    pub tab_width: usize,

    /// Whether or not to simply loop through all input (`cat` mode)
    pub loop_through: bool,

    /// Whether or not the output should be colorized
    pub colored_output: bool,

    /// Whether or not the output terminal supports true color
    pub true_color: bool,

    /// Style elements (grid, line numbers, ...)
    pub style_components: StyleComponents,

    /// If and how text should be wrapped
    pub wrapping_mode: WrappingMode,

    /// Pager or STDOUT
    #[cfg(feature = "paging")]
    pub paging_mode: PagingMode,

    /// Specifies which lines should be printed
    pub visible_lines: VisibleLines,

    /// The syntax highlighting theme
    pub theme: String,

    /// File extension/name mappings
    pub syntax_mapping: SyntaxMapping<'a>,

    /// Command to start the pager
    pub pager: Option<&'a str>,

    /// Whether or not to use ANSI italics
    pub use_italic_text: bool,

    /// Ranges of lines which should be highlighted with a special background color
    pub highlighted_lines: HighlightedLineRanges,

    /// Whether or not to allow custom assets. If this is false or if custom assets (a.k.a.
    /// cached assets) are not available, assets from the binary will be used instead.
    pub use_custom_assets: bool,

    // Whether or not to use $LESSOPEN if set
    #[cfg(feature = "lessopen")]
    pub use_lessopen: bool,

    // Weather or not to set terminal title when using a pager
    pub set_terminal_title: bool,

    /// The maximum number of consecutive empty lines to display
    pub squeeze_lines: Option<usize>,

    // Weather or not to set terminal title when using a pager
    pub strip_ansi: StripAnsiMode,
}

impl<'a> Config<'a> {
    #[cfg(feature = "paging")]
    pub fn resolve_output_layout(
        &self,
        inputs: &[Input],
        style_components: &StyleComponents,
        syntax_mapping: &SyntaxMapping,
        extra_plain: bool,
        no_paging: bool,
        interactive_output: bool,
        paging_arg: Option<&str>,
        wrap_arg: Option<&str>,
        chop_long_lines: bool,
        maybe_term_width: Option<usize>,
        tab_width: Option<usize>,
    ) -> (PagingMode, WrappingMode, usize) {
        let mapping_ready = !syntax_mapping.custom_mappings().is_empty()
            || !syntax_mapping.ignored_suffixes.values.is_empty();

        let reads_from_stdin = inputs.iter().any(|input| {
            let description = &input.description;
            let metadata = &input.metadata;
            let has_display_name = !description.title().is_empty();
            let has_kind = description
                .kind()
                .map(|kind| !kind.is_empty())
                .unwrap_or(true);
            let has_summary = !description.summary().is_empty();
            let named_source = metadata
                .user_provided_name
                .as_ref()
                .map(|name| !name.as_os_str().is_empty())
                .unwrap_or(true);

            matches!(input.kind, InputKind::StdIn)
                && has_display_name
                && has_kind
                && has_summary
                && named_source
        });

        let paging_mode = match paging_arg {
            Some("always") => PagingMode::Always,
            Some("never") => self.paging_mode,
            Some("auto") | None => {
                if (extra_plain || no_paging) && mapping_ready {
                    self.paging_mode
                } else if reads_from_stdin {
                    if interactive_output && !std::io::stdin().is_terminal() {
                        PagingMode::QuitIfOneScreen
                    } else {
                        self.paging_mode
                    }
                } else if interactive_output {
                    PagingMode::QuitIfOneScreen
                } else {
                    self.paging_mode
                }
            }
            _ => unreachable!("other values for --paging are not allowed"),
        };

        let plain_style = style_components
            .0
            .iter()
            .all(|component| component == &StyleComponent::Plain);

        let wrapping_mode = if interactive_output || maybe_term_width.is_some() {
            if !chop_long_lines {
                match wrap_arg {
                    Some("character") => WrappingMode::Character,
                    Some("never") => WrappingMode::NoWrapping(true),
                    Some("auto") | None => {
                        if plain_style {
                            WrappingMode::NoWrapping(false)
                        } else {
                            WrappingMode::Character
                        }
                    }
                    _ => unreachable!("other values for --wrap are not allowed"),
                }
            } else {
                WrappingMode::NoWrapping(true)
            }
        } else {
            WrappingMode::NoWrapping(false)
        };

        let tab_width = tab_width.unwrap_or(if plain_style && paging_mode == PagingMode::Never {
            0
        } else {
            4
        });

        (paging_mode, wrapping_mode, tab_width)
    }
}

#[cfg(all(feature = "minimal-application", feature = "paging"))]
pub fn get_pager_executable(config_pager: Option<&str>) -> Option<String> {
    crate::pager::get_pager(config_pager)
        .ok()
